window.KAHANOV_QUIZZES = [{"number":1,"questions":[{"number":1,"prompt":"The National Athletic Trainers Association was formed in which year?","type":"single","options":[{"label":"a","text":"1945","correct":false},{"label":"b","text":"1953","correct":false},{"label":"c","text":"1950","correct":true},{"label":"d","text":"1960","correct":false}]},{"number":2,"prompt":"Which of these organizations is responsible for the regulation of educational programs in athletic training?","type":"single","options":[{"label":"a","text":"National Athletic Trainers Association","correct":false},{"label":"b","text":"Board of Certification","correct":false},{"label":"c","text":"The NATA Research and Education Foundation","correct":false},{"label":"d","text":"Commission on Accreditation of Athletic Training Education","correct":true}]},{"number":3,"prompt":"The BOC identifies five practice domains of athletic training. Name three of the five BOC practice domains?","type":"multiple","options":[{"label":"a","text":"Risk Reduction, Wellness, and Health Literacy","correct":false},{"label":"b","text":"Assessment, Evaluation, and Diagnosis","correct":true},{"label":"c","text":"Critical Incident Management","correct":false},{"label":"d","text":"Therapeutic Intervention","correct":true},{"label":"e","text":"Health Care Administration and Professional Responsibility","correct":true}]},{"number":4,"prompt":"Which organization is responsible for monitoring policies and professional affiliation for athletic trainers?","type":"single","options":[{"label":"a","text":"National Athletic Trainers Association","correct":true},{"label":"b","text":"Board of Certification","correct":false},{"label":"c","text":"The NATA Research and Education Foundation","correct":false},{"label":"d","text":"Commission on Accreditation of Athletic Training Education","correct":false}]},{"number":5,"prompt":"The purpose of continuing education requirements is to ensure that athletic trainers are practicing by applying current research to all aspects of professional practice.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":6,"prompt":"The CAATE has identified specialty areas in athletic training approved for post-professional residencies. Which of these is the CAATE-approved specialty area?","type":"single","options":[{"label":"a","text":"concussion management","correct":false},{"label":"b","text":"rehabilitation","correct":true},{"label":"c","text":"the tactical athlete","correct":false},{"label":"d","text":"collegiate athletics","correct":false}]},{"number":7,"prompt":"The definition of interprofessional education (IPE) is education that occurs when two or more professions learn with, about, and from each other to enable effective collaboration and improve health outcomes.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":8,"prompt":"Which of these would NOT be considered a member of the athletic training health care team?","type":"single","options":[{"label":"a","text":"physical therapist","correct":false},{"label":"b","text":"sport psychologist","correct":false},{"label":"c","text":"podiatrist","correct":false},{"label":"d","text":"tactical supervisor","correct":false},{"label":"e","text":"none of the above","correct":true}]},{"number":9,"prompt":"Which of these is an IPEC interprofessional education core competency domain?","type":"single","options":[{"label":"a","text":"interprofessional communication","correct":true},{"label":"b","text":"prevention, health promotion, and wellness","correct":false},{"label":"c","text":"primary care","correct":false},{"label":"d","text":"professionalism","correct":false}]},{"number":10,"prompt":"The physician should always be the leader of the health care team.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]}]},{"number":2,"questions":[{"number":1,"prompt":"What is evidence-based practice?","type":"single","options":[{"label":"a","text":"a blueprint for diagnosis, treatment, or therapy in health care","correct":false},{"label":"b","text":"a guarantee that research is available to answer clinical questions","correct":false},{"label":"c","text":"the application of research that may prove or disprove an accepted method, treatment, therapy, diagnostic procedure, or preventative measure","correct":true},{"label":"d","text":"used in isolation without incorporating clinical skills and the patient","correct":false}]},{"number":2,"prompt":"Which of these research designs is a highly structured, rigorous research method that identifies, critically appraises, and synthesizes all available studies addressing a specific research question?","type":"single","options":[{"label":"a","text":"cohort study","correct":false},{"label":"b","text":"controlled trial","correct":false},{"label":"c","text":"systematic review","correct":true},{"label":"d","text":"meta-analysis","correct":false}]},{"number":3,"prompt":"What is a research design used to evaluate the effectiveness of an intervention by comparing it against a standard baseline?","type":"single","options":[{"label":"a","text":"a cohort study","correct":false},{"label":"b","text":"a case study","correct":false},{"label":"c","text":"a controlled trial","correct":true},{"label":"d","text":"a systematic review","correct":false}]},{"number":4,"prompt":"Which of these is considered to have the stronger level of evidence?","type":"single","options":[{"label":"a","text":"a single integrated study that is descriptive in nature","correct":false},{"label":"b","text":"qualitative research","correct":false},{"label":"c","text":"a randomized controlled trial","correct":true},{"label":"d","text":"a well-designed cohort study","correct":false}]},{"number":5,"prompt":"Qualitative research is a strategic framework for collecting, analyzing, and interpreting nonnumerical data.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":6,"prompt":"Individuals with acute 1° ankle sprains were randomly grouped into a control group and a group given Ibuprofen as part of the treatment regime and then asked how they feel daily for 2 weeks. This is an example of which type of research?","type":"single","options":[{"label":"a","text":"descriptive","correct":true},{"label":"b","text":"causal-comparative","correct":false},{"label":"c","text":"correlational","correct":false},{"label":"d","text":"experimental research","correct":false}]},{"number":7,"prompt":"When critically appraising the literature, the clinician should first __________.","type":"single","options":[{"label":"a","text":"assess if the research methodology is appropriate for the research question.","correct":true},{"label":"b","text":"assume that if the conclusions of the literature suggest something different than common practice, it is biased.","correct":false},{"label":"c","text":"scrutinize the data collection and process.","correct":false},{"label":"d","text":"determine if the findings presented are consistent with the data analysis.","correct":false}]},{"number":8,"prompt":"What is the purpose of disablement models such as the ICF or Nagi model?","type":"single","options":[{"label":"a","text":"To be able to draw a conclusion as to whether the literature is trustworthy and valuable enough to make clinical decisions.","correct":false},{"label":"b","text":"To provide structure to assess patient health status that accounts for the person and the environment.","correct":true},{"label":"c","text":"To standardize all patient rehabilitation protocols.","correct":false},{"label":"d","text":"To shift the focus away from patient function and focus on the disease or injury at hand.","correct":false}]},{"number":9,"prompt":"Which of these is a strategy for assessing the usefulness of including research into clinical decision making?","type":"single","options":[{"label":"a","text":"ICF model","correct":false},{"label":"b","text":"PICO framework","correct":true},{"label":"c","text":"comparison and outcome model","correct":false},{"label":"d","text":"Nagi model","correct":false}]},{"number":10,"prompt":"Which of these statements is true about a test that has high sensitivity and low specificity?","type":"single","options":[{"label":"a","text":"The test identifies a particular injury at a high rate but has a high rate of false positives.","correct":true},{"label":"b","text":"The test would result in a low rate of false positives and a high rate of false negatives.","correct":false},{"label":"c","text":"The test will poorly identify a particular injury but will have a high rate of false positives.","correct":false},{"label":"d","text":"The test will poorly identify a particular injury but will have a low rate of false positives.","correct":false}]}]},{"number":3,"questions":[{"number":1,"prompt":"The primary function of public health is to train health care providers for individualized health.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":2,"prompt":"Which of these is a recognized sports injury surveillance system?","type":"single","options":[{"label":"a","text":"American Society for Testing Materials (ATSM) Injury Research","correct":false},{"label":"b","text":"National Center for Catastrophic Sport Injury Research (NCCSIR)","correct":true},{"label":"c","text":"International Classification of Diseases (ICD-10)","correct":false},{"label":"d","text":"DSM-5","correct":false}]},{"number":3,"prompt":"Which of these is one of the most commonly used methods to ensure athletic injuries are recorded in the same way within injury surveillance systems?","type":"single","options":[{"label":"a","text":"Orchard Sports Injury Classification System","correct":true},{"label":"b","text":"CPT Code System","correct":false},{"label":"c","text":"NCAA Injury Surveillance System","correct":false},{"label":"d","text":"ICD-11","correct":false}]},{"number":4,"prompt":"Which of these best describes the term likelihood of an unwanted outcome as it relates to measuring the severity of its consequences?","type":"single","options":[{"label":"a","text":"actual number of days or events in which the patient participated","correct":false},{"label":"b","text":"how often new cases of the condition occur","correct":false},{"label":"c","text":"the proportion of people affected by a condition at any given time","correct":false},{"label":"d","text":"the probability of an adverse event or consequence","correct":true}]},{"number":5,"prompt":"Which of these is an approach that addresses health disparities, such as asthma, that disproportionately impact children of low socioeconomic status and have a greater prevalence in minority populations?","type":"single","options":[{"label":"a","text":"illness surveillance systems","correct":false},{"label":"b","text":"social determinants of health","correct":true},{"label":"c","text":"primary prevention","correct":false},{"label":"d","text":"health care access","correct":false}]},{"number":6,"prompt":"Which of these best describes primary prevention?","type":"single","options":[{"label":"a","text":"An AT implements a shoulder-strengthening program for their patients to prevent a rotator cuff injury from occurring in the first place.","correct":true},{"label":"b","text":"An athletic trainer recognizes the signs and symptoms of a rotator cuff tendinopathy early and begins treatment and rehabilitation prior to the patient suffering a rotator cuff tear.","correct":false},{"label":"c","text":"The rotator cuff is torn, and the patient is not a candidate for surgery, but the athletic trainer provides rehabilitation to help the patient manage the injury.","correct":false},{"label":"d","text":"The AT fits some of the football linemen with shoulder braces to prevent abduction and external rotation of the shoulder.","correct":false}]},{"number":7,"prompt":"Using both health records and injury surveillance systems is essentially a duplicate process, so the athletic trainer should determine which one to use to create prevention programs.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"According to the Orchard Sports Injury and Illness Classification System, what does the first letter in an injury code listed as “KLM” refer to?","type":"single","options":[{"label":"a","text":"the tissue type","correct":false},{"label":"b","text":"pathology type","correct":false},{"label":"c","text":"body part","correct":true},{"label":"d","text":"etiology","correct":false}]},{"number":9,"prompt":"Which of these would be considered an intrinsic risk factor?","type":"single","options":[{"label":"a","text":"equipment","correct":false},{"label":"b","text":"fitness level","correct":true},{"label":"c","text":"tactical work shift","correct":false},{"label":"d","text":"weather","correct":false}]},{"number":10,"prompt":"A health disparity occurs when people with lower education or incomes, or of specific races or ethnic backgrounds, are researched more often to determine chronic disease.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]}]},{"number":4,"questions":[{"number":1,"prompt":"There is persuasive evidence that delivering health care in a responsive and respectful way through knowing patients’ preferences and valuing and engaging the patient in decisions regarding his treatment plan improves patient outcomes in a variety of settings. What is the name of this focus of health care?","type":"single","options":[{"label":"a","text":"person/patient-centered care","correct":true},{"label":"b","text":"person-first care","correct":false},{"label":"c","text":"identity-based care","correct":false},{"label":"d","text":"personal core values","correct":false}]},{"number":2,"prompt":"A group of people with a distinct shared ancestry and cultural identity is called a _________.","type":"single","options":[{"label":"a","text":"race","correct":false},{"label":"b","text":"language","correct":false},{"label":"c","text":"ethnicity","correct":true},{"label":"d","text":"culture","correct":false}]},{"number":3,"prompt":"The use of salutations is important and sets the tone for the relationship with your patient. Their use in different cultures is influenced by _______________, which refers to the level of comfort group members have with power, influence, and wealth inequalities.","type":"written","referenceAnswer":"power distance"},{"number":4,"prompt":"Pain management may be impacted by the patient’s culture. What do you have to consider as a health care provider when dealing with a patient who is emotive versus a patient who is stoic?","type":"written","referenceAnswer":"A stoic patient may not show emotion after a painful (or pleasurable) experience, whereas someone who is emotive may overly express emotions during these same experiences. The clinician must understand that it is not whether pain is experienced by the patient but rather how pain is expressed by the patient."},{"number":5,"prompt":"Race is a social construct and a societal category that is grounded in DNA analysis.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":6,"prompt":"_______________ is the result of unconscious judgment and behavior toward members of a social group or groups.","type":"written","referenceAnswer":"Implicit bias"},{"number":7,"prompt":"Oppression refers to appropriate treatment on people based of status and perpetuates health disparities in patient interactions, treatment decisions, treatment compliance, and health outcomes.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"Which of these is a type of microaggression?","type":"single","options":[{"label":"a","text":"microvalidation","correct":false},{"label":"b","text":"microbias","correct":false},{"label":"c","text":"microinequality","correct":false},{"label":"d","text":"microinvalidations","correct":true}]},{"number":9,"prompt":"What is the term for the differences across social groups between prevalence of disease or injury, access to health care, and patient outcomes?","type":"single","options":[{"label":"a","text":"health care inequities","correct":false},{"label":"b","text":"cultural differences","correct":false},{"label":"c","text":"health care disparities","correct":true},{"label":"d","text":"racial disparities","correct":false}]},{"number":10,"prompt":"Which of these is a framework for cross-cultural communication that helps build mutual understanding and enhances patient care?","type":"single","options":[{"label":"a","text":"the DCAPS-BTL framework","correct":false},{"label":"b","text":"the LEARN model","correct":true},{"label":"c","text":"the EMPATHY model","correct":false},{"label":"d","text":"the PEARL model","correct":false}]}]},{"number":5,"questions":[{"number":1,"prompt":"Regardless of employment setting, health care administrators have the same role in coordinating and supervising all of these EXCEPT _________.","type":"single","options":[{"label":"a","text":"budgets","correct":false},{"label":"b","text":"services","correct":false},{"label":"c","text":"administrative operations","correct":false},{"label":"d","text":"fundraising","correct":true}]},{"number":2,"prompt":"Which of these would be considered an external factor of health care administration?","type":"single","options":[{"label":"a","text":"budget","correct":false},{"label":"b","text":"stakeholders (board, patients, or clients)","correct":false},{"label":"c","text":"personnel","correct":false},{"label":"d","text":"accreditation","correct":true}]},{"number":3,"prompt":"What is an organizational structure that features decentralization, team-based collaboration with cross-functional groups?","type":"single","options":[{"label":"a","text":"functional organizational structure","correct":false},{"label":"b","text":"team-based model","correct":false},{"label":"c","text":"service line model","correct":false},{"label":"d","text":"contemporary model","correct":true}]},{"number":4,"prompt":"The Affordable Care Act of 2010 mandated socialized health care in addition to regulations regarding electronic health care and set limits on disclosure of protected health information.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":5,"prompt":"Which of these accredits nearly 21,000 health care organizations and programs in the United States to ensure patient safety?","type":"single","options":[{"label":"a","text":"Commission on Systemic Interoperability Accreditation","correct":false},{"label":"b","text":"Commission on Accreditation of Athletic Training Education","correct":false},{"label":"c","text":"Public Health Data Standards Consortium","correct":false},{"label":"d","text":"Joint Commission: Accreditation of Health Care Organizations","correct":true}]},{"number":6,"prompt":"Continuous quality improvement processes use quantitative data to establish desired outcomes, such as patient satisfaction with services; qualitative data is NOT typically used to measure patient outcomes.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":7,"prompt":"List two and describe quality improvement models described in this chapter.","type":"written","referenceAnswer":"lean model, model for improvement, FACE, six sigma"},{"number":8,"prompt":"The written patient consent prior to a medical intervention should include all of these EXCEPT __________.","type":"single","options":[{"label":"a","text":"diagnosis or potential diagnoses","correct":false},{"label":"b","text":"details regarding the intervention and reasons for intervention","correct":false},{"label":"c","text":"total costs of the intervention","correct":true},{"label":"d","text":"potential burdens and risks of both the intervention and forgoing the recommendation","correct":false}]},{"number":9,"prompt":"Characteristics that define “big data” in health care include all of the following EXCEPT __________.","type":"single","options":[{"label":"a","text":"volume","correct":false},{"label":"b","text":"veracity","correct":true},{"label":"c","text":"velocity","correct":false},{"label":"d","text":"variety","correct":false}]},{"number":10,"prompt":"Which of these is considered a common global health insurance policy within athletic departments?","type":"single","options":[{"label":"a","text":"Medicare","correct":false},{"label":"b","text":"Tri-care","correct":false},{"label":"c","text":"Medicaid","correct":false},{"label":"d","text":"secondary coverage","correct":true}]}]},{"number":6,"questions":[{"number":1,"prompt":"The organization’s identity is most likely to be communicated through which of these?","type":"single","options":[{"label":"a","text":"strategic and operational plans","correct":false},{"label":"b","text":"mission and vision","correct":true},{"label":"c","text":"management and leadership","correct":false},{"label":"d","text":"leadership and positions of power","correct":false}]},{"number":2,"prompt":"Leadership is function of __________.","type":"single","options":[{"label":"a","text":"creating and managing policies.","correct":false},{"label":"b","text":"creating a vision and direction.","correct":true},{"label":"c","text":"controlling organizational resources.","correct":false},{"label":"d","text":"ensuing the solvency of the organization.","correct":false}]},{"number":3,"prompt":"List two of the three distinct management roles.","type":"written","referenceAnswer":"interpersonal, knowledge, decisional"},{"number":4,"prompt":"In any organization, leaders can be both in a position of power and authority or personal influence.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":5,"prompt":"Motivating employees through influence others based on specialized knowledge, skills, or deep experience is an example of which type of power?","type":"single","options":[{"label":"a","text":"expert power","correct":true},{"label":"b","text":"connection power","correct":false},{"label":"c","text":"legitimate power","correct":false},{"label":"d","text":"reward power","correct":false}]},{"number":6,"prompt":"Which of these refers to the awareness and capacity to control one’s own emotions and manage the emotions of others through interprofessional relationships?","type":"single","options":[{"label":"a","text":"emotional intelligence","correct":true},{"label":"b","text":"leadership skills","correct":false},{"label":"c","text":"networking skills","correct":false},{"label":"d","text":"interpersonal skills","correct":false}]},{"number":7,"prompt":"Which type of leadership participates in heard decision-making, open communication, and collective problem-solving to develop trust?","type":"single","options":[{"label":"a","text":"collaborative leadership","correct":true},{"label":"b","text":"consensus leadership","correct":false},{"label":"c","text":"servant leadership","correct":false},{"label":"d","text":"transactional leadership","correct":false}]},{"number":8,"prompt":"What is the main difference between strategic planning and operational planning?","type":"written","referenceAnswer":"Strategic plans identify organizational goals while identifying internal and external outcomes. The operation plan is a working plan and includes who is responsible for completing long- and short-term goals."},{"number":9,"prompt":"Your athletic training clinic just ultrasound gel and disposable electrodes for $6,000. On which budget line would this purchase be posted?","type":"single","options":[{"label":"a","text":"operating budget","correct":false},{"label":"b","text":"capital budget","correct":false},{"label":"c","text":"expendable supplies","correct":true},{"label":"d","text":"accounts payable","correct":false}]},{"number":10,"prompt":"The identification, evaluation, and prioritization of risks to an organization or institution that is mediated by policy, budget, or other application of resources to mitigate potential harm to the organization, employees, or patients and clients are called _______________.","type":"written","referenceAnswer":"strategic planning"}]},{"number":7,"questions":[{"number":1,"prompt":"Which of these means of exposure to bloodborne pathogens is NOT typically associated with occupational exposure for a health care worker?","type":"single","options":[{"label":"a","text":"direct contact","correct":false},{"label":"b","text":"indirect contact","correct":false},{"label":"c","text":"airborne contact","correct":false},{"label":"d","text":"vector-borne contact","correct":true}]},{"number":2,"prompt":"Which of these is contracted from poor sanitary conditions, contaminated drinking water, or fecal-oral transfer?","type":"single","options":[{"label":"a","text":"hepatitis A","correct":true},{"label":"b","text":"hepatitis B","correct":false},{"label":"c","text":"hepatitis D","correct":false},{"label":"d","text":"HIV","correct":false}]},{"number":3,"prompt":"The average risk of HIV infection after a needlestick or laceration exposure to HIV-infected blood is 50%.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":4,"prompt":"When a provider experiences a “specific eye, mouth, other mucous membrane, non-intact, or parenteral contact with blood or other potentially infectious materials that result from the performance of an employee’s duties, often as a result of a needlestick, sharps injury, or improper/faulty PPE usage,” it is called _________.","type":"single","options":[{"label":"a","text":"contamination","correct":false},{"label":"b","text":"exposure incident","correct":true},{"label":"c","text":"accident","correct":false},{"label":"d","text":"occupational exposure","correct":false}]},{"number":5,"prompt":"Which of these would NOT require the use of PPE for treating a patient with a laceration in the athletic training clinic?","type":"single","options":[{"label":"a","text":"latex or nitrile gloves","correct":false},{"label":"b","text":"washing hands or using hand sanitizer","correct":false},{"label":"c","text":"use of a face shield or goggles","correct":true},{"label":"d","text":"disposing of blood-soaked gauze in hazardous waste","correct":false}]},{"number":6,"prompt":"What are the controls that isolate or remove the bloodborne pathogens hazard from the workplace?","type":"single","options":[{"label":"a","text":"PPE controls","correct":false},{"label":"b","text":"work practice controls","correct":false},{"label":"c","text":"OSHA controls","correct":false},{"label":"d","text":"engineering controls","correct":true}]},{"number":7,"prompt":"If both handwashing facilities and hand sanitizer are available, the health care provider should use the hand sanitizer since the alcohol-based hand sanitizer is more effective in reducing the number of germs on the hands.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"What is the recommended sequence for donning PPEs?","type":"single","options":[{"label":"a","text":"gloves, gown, protective eyewear, mask","correct":false},{"label":"b","text":"gown, mask, protective eyewear, gloves","correct":true},{"label":"c","text":"mask, gown, gloves, barrier devices","correct":false},{"label":"d","text":"gown, mask, gloves, protective eyewear","correct":false}]},{"number":9,"prompt":"The ECP must be accessible to personnel at all times and must be reviewed and updated at least every two years.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":10,"prompt":"What are the policies that reduce the likelihood of exposure by altering the manner in which a task is performed, such as prohibiting recapping of needles by a two-handed technique?","type":"single","options":[{"label":"a","text":"work practice controls","correct":true},{"label":"b","text":"engineering controls","correct":false},{"label":"c","text":"environmental controls","correct":false},{"label":"d","text":"OSHA controls","correct":false}]}]},{"number":8,"questions":[{"number":1,"prompt":"What is a benefit of office-based PPE versus station-based PPE?","type":"single","options":[{"label":"a","text":"lower cost","correct":false},{"label":"b","text":"Physician is familiar with sport requirements.","correct":false},{"label":"c","text":"previous relationship with primary care physician","correct":true},{"label":"d","text":"ability for immediate referral to specialists on site","correct":false}]},{"number":2,"prompt":"An ECG is recommended as an essential component of all PPEs.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":3,"prompt":"Which of these is a recommendation for PPE?","type":"single","options":[{"label":"a","text":"The PPE must be completed, at a minimum, annually.","correct":false},{"label":"b","text":"The PPE should be completed 1 or 2 days prior to the start of the season.","correct":false},{"label":"c","text":"The PPE should be completed at each new level of participation.","correct":true},{"label":"d","text":"The PPE should be completed at least every 2 years.","correct":false}]},{"number":4,"prompt":"What is the term for the body’s ability to maintain a normal core temperature?","type":"single","options":[{"label":"a","text":"homeostasis","correct":false},{"label":"b","text":"heat exchange","correct":false},{"label":"c","text":"thermoregulation","correct":true},{"label":"d","text":"temperature gradient","correct":false}]},{"number":5,"prompt":"The two most important factors affecting the way the cardiovascular system responds to exercise in hyperthermic environments are _________ and __________.","type":"written","referenceAnswer":"fitness level; acclimatization"},{"number":6,"prompt":"Fluid replacement is a modifiable factor that can reduce the risk of developing heat illness. People should strive to have body mass losses of less than what during exercise?","type":"single","options":[{"label":"a","text":"2%","correct":true},{"label":"b","text":"5%","correct":false},{"label":"c","text":"10%","correct":false},{"label":"d","text":"10 lb (4.5 kg)","correct":false}]},{"number":7,"prompt":"Hypothermia is defined as a core temperature below","type":"single","options":[{"label":"a","text":"34 °C (93.2 °F)","correct":false},{"label":"b","text":"35 °C (95 °F)","correct":true},{"label":"c","text":"37 °C (98.6 °F)","correct":false},{"label":"d","text":"39 °C (102.2 °F)","correct":false}]},{"number":8,"prompt":"Which of these patients would be the most susceptible to heat-related injury?","type":"single","options":[{"label":"a","text":"A white female who is well acclimatized and within 2% of her first practice weight.","correct":false},{"label":"b","text":"A black male weighing 240 lb (108.86 kg) before the first practice and weighing 218 lb (98.88 kg) before the fourth practice.","correct":true},{"label":"c","text":"A white male who is 18% body fat.","correct":false},{"label":"d","text":"A black female weighs 135 lb (61.23 kg) before practice and 129 lb (58.51 kg) after the second practice.","correct":false}]},{"number":9,"prompt":"The athletic trainer has been monitoring the thunderstorm over the practice fields. The last sound of thunder occurred 10 minutes ago. The coach asks when the team can resume practice. What advice should the AT give to the coach?","type":"single","options":[{"label":"a","text":"Head out to the practice fields; it seems that the thunderstorm has passed.","correct":false},{"label":"b","text":"The team should not go back to the fields until the thunderstorm has completely passed and the sun is shining.","correct":false},{"label":"c","text":"The team needs to wait an additional 20 minutes before heading back to practice.","correct":true},{"label":"d","text":"The team needs to wait an additional 30 minutes before heading out to practice.","correct":false}]},{"number":10,"prompt":"The athletic trainer working at the industrial plant has several workers and patients who are complaining of shoulder pain. Most of the complaints are from workers that are required to work in “overhead” jobs. Which of these would be considered an application of ergonomics?","type":"single","options":[{"label":"a","text":"Suggest to the foreman that the workers complaining of shoulder pain be given at least two days off from work","correct":false},{"label":"b","text":"Send the workers for rehabilitation on their shoulders","correct":false},{"label":"c","text":"Work with the patients to ensure that they have good posture and appropriate technique when completing their jobs","correct":true},{"label":"d","text":"Suggest to the foreman that the workers switch to another job for a few weeks","correct":false}]}]},{"number":9,"questions":[{"number":1,"prompt":"Which of these statements most accurately reflects the effects of leisure time physical activity on mortality?","type":"single","options":[{"label":"a","text":"Consistent exercise to a point contributed to lower mortality, but vigorous exercise increased inflammation and antioxidants, leading to increased mortality rates.","correct":false},{"label":"b","text":"Consistent exercise versus consistent physical inactivity contributed to lower all-cause mortality and cardiovascular disease mortality risk.","correct":true},{"label":"c","text":"Leisure-time activity started early in life decreased all-cause mortality by > 20%, but leisure-time activity started later in life had minimal effects on mortality.","correct":false},{"label":"d","text":"Leisure-time activity of 10 to 15 hours per week resulted in a 14% lower risk of cancer mortality.","correct":false}]},{"number":2,"prompt":"Which of these is NOT typically associated with type 2 diabetes?","type":"single","options":[{"label":"a","text":"smoking","correct":false},{"label":"b","text":"increased body mass","correct":false},{"label":"c","text":"low physical activity","correct":false},{"label":"d","text":"heredity","correct":true}]},{"number":3,"prompt":"Exercise positively impacts sleep, particularly in middle- and older-aged people.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":4,"prompt":"The gold standard measure of cardiorespiratory fitness is maximal oxygen consumption or V̇O2max. Which of these estimates V̇O2max by measuring the response of heart rate to exercise?","type":"single","options":[{"label":"a","text":"12-minute run","correct":false},{"label":"b","text":"3-mile run","correct":false},{"label":"c","text":"Rockport walking test","correct":true},{"label":"d","text":"Cooper 1.5-mile run","correct":false}]},{"number":5,"prompt":"Which of these is the ability to produce a high rate of force over a short period of time?","type":"single","options":[{"label":"a","text":"strength","correct":false},{"label":"b","text":"endurance","correct":false},{"label":"c","text":"power","correct":true},{"label":"d","text":"muscular fitness","correct":false}]},{"number":6,"prompt":"What is the ACSM recommendation for the minimum number of minutes per week of moderate-intensity exercise needed for a modest amount of weight loss to improve health?","type":"single","options":[{"label":"a","text":"60","correct":false},{"label":"b","text":"150","correct":true},{"label":"c","text":"200","correct":false},{"label":"d","text":"320","correct":false}]},{"number":7,"prompt":"Which of these is the most efficient method of assessing body fat composition for all patients during their PPE held in the evening hours at a high school with limited resources?","type":"single","options":[{"label":"a","text":"DEXA","correct":false},{"label":"b","text":"Bod Pod","correct":false},{"label":"c","text":"skinfold","correct":true},{"label":"d","text":"underwater weighing","correct":false}]},{"number":8,"prompt":"What is the star excursion test?","type":"single","options":[{"label":"a","text":"a test for concentric strength","correct":false},{"label":"b","text":"a measure of flexibility","correct":false},{"label":"c","text":"a test for static balance","correct":false},{"label":"d","text":"a measure of dynamic balance","correct":true}]},{"number":9,"prompt":"When designing a fitness program, what does the concept of progression refer to?","type":"single","options":[{"label":"a","text":"the FITT principle","correct":false},{"label":"b","text":"changes in the prescription over time","correct":true},{"label":"c","text":"the progressive and systematic increase in the load, duration, or frequency of the exercise","correct":false},{"label":"d","text":"the benefits of exercise that occur to the systems of the body carrying out the exercise","correct":false}]},{"number":10,"prompt":"A physically fit person with a consistent exercise routine decides to train for a marathon. She is moving from the __________ to the __________ phase of exercise programing.","type":"single","options":[{"label":"a","text":"initial; maintenance","correct":false},{"label":"b","text":"maintenance; improvement","correct":true},{"label":"c","text":"maintenance; initial","correct":false},{"label":"d","text":"improvement; initial","correct":false}]}]},{"number":10,"questions":[{"number":1,"prompt":"List the six essential nutrients.","type":"written","referenceAnswer":"carbohydrate, protein, fat, vitamins, minerals, water"},{"number":2,"prompt":"The body uses several energy systems, depending on the duration and intensity of the activity. Which of these systems is the primary source of energy for explosive short-duration energy needs (10 seconds to 2 minutes)?","type":"single","options":[{"label":"a","text":"glycolysis","correct":false},{"label":"b","text":"oxidative from carbohydrates","correct":false},{"label":"c","text":"oxidative from fats","correct":false},{"label":"d","text":"ATP-PC","correct":true}]},{"number":3,"prompt":"Which of the following is NOT a macronutrient?","type":"single","options":[{"label":"a","text":"carbohydrates","correct":false},{"label":"b","text":"minerals","correct":true},{"label":"c","text":"protein","correct":false},{"label":"d","text":"fat","correct":false}]},{"number":4,"prompt":"Activities done at high intensity that surpass the ability of the heart and lungs to supply oxygen to working muscles will rely chiefly on what for fuels?","type":"single","options":[{"label":"a","text":"protein","correct":false},{"label":"b","text":"glucose","correct":true},{"label":"c","text":"glycogen","correct":false},{"label":"d","text":"fatty acids","correct":false}]},{"number":5,"prompt":"Essential amino acids are NOT necessary to consume because our body synthesizes them.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":6,"prompt":"Following a distal fibular fracture, Tamesha wants to improve her diet to ensure she is providing the optimal healing environment for her injury. You suggest that for optimal bone health she increase her intake of vitamin D and calcium. Tamesha does NOT like milk. What foods could she eat to increase her intake of these vitamins and minerals without taking supplements?","type":"single","options":[{"label":"a","text":"wheat-germ oil, sunflower seeds, milk","correct":false},{"label":"b","text":"oysters, white beans, dark chocolate","correct":false},{"label":"c","text":"tuna fish, yogurt, soybeans, egg, broccoli","correct":true},{"label":"d","text":"pumpkin seeds, almonds, red peppers, cheese","correct":false}]},{"number":7,"prompt":"What is the recommended daily water intake for females?","type":"single","options":[{"label":"a","text":"1.0-1.5 L","correct":false},{"label":"b","text":"2.1-2.7 L","correct":true},{"label":"c","text":"3.7-4.1 L","correct":false},{"label":"d","text":"3.0-3.5 L","correct":false}]},{"number":8,"prompt":"For most athletes, sports drinks are far superior to water in providing the appropriate hydration during strenuous physical activity.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":9,"prompt":"Which of these best describes low energy availability?","type":"single","options":[{"label":"a","text":"when a patient skips a meal prior to workout","correct":false},{"label":"b","text":"when a patient has a disrupted menstrual cycle, low body fat, and bone mineral loss","correct":false},{"label":"c","text":"when a patient does not have sufficient calories for the body’s requirements and for exercise","correct":true},{"label":"d","text":"when the body does not have enough glucose for energy and burns stored fats instead","correct":false}]},{"number":10,"prompt":"Which of these is true about supplements?","type":"single","options":[{"label":"a","text":"All supplements are banned by the International Olympic Committee (IOC).","correct":false},{"label":"b","text":"Supplements are strictly regulated by the FDA.","correct":false},{"label":"c","text":"The supplement industry is a “buyer beware” market.","correct":true},{"label":"d","text":"Ergogenic aid is another term for dietary supplements.","correct":false}]}]},{"number":11,"questions":[{"number":1,"prompt":"Which of these associations certifies helmets for use in all levels of football competition?","type":"single","options":[{"label":"a","text":"Riddell Testing Standards Committee (RTSC)","correct":false},{"label":"b","text":"National Operating Committee on Standards for Athletic Equipment (NOCSAE)","correct":true},{"label":"c","text":"Sports and Fitness Industry Association (SFIA)","correct":false},{"label":"d","text":"American Society for Testing Materials (ASTM)","correct":false}]},{"number":2,"prompt":"Which of these is true regarding proper fit of a football helmet?","type":"single","options":[{"label":"a","text":"The face mask should be two finger widths from the nose.","correct":false},{"label":"b","text":"The forehead pad should rest one in. above the eyebrows.","correct":true},{"label":"c","text":"The ear holes on the helmet should align with the athlete’s ears, and the back of the helmet should be at the level of the sixth cervical vertebra.","correct":false},{"label":"d","text":"When you press down on the crown of the head, the athlete should feel pressure just above the eyebrows.","correct":false}]},{"number":3,"prompt":"Field hockey is considered in which risk category for sport-related eye injury?","type":"single","options":[{"label":"a","text":"low","correct":false},{"label":"b","text":"moderate","correct":true},{"label":"c","text":"high","correct":false},{"label":"d","text":"eye safe","correct":false}]},{"number":4,"prompt":"In a study by the American Dental Association, mouthguards were found to reduce both the rate and severity of concussions.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":5,"prompt":"In which of these football positions would an athlete be most likely to wear a cantilevered shoulder pad?","type":"single","options":[{"label":"a","text":"quarterback","correct":false},{"label":"b","text":"offensive lineman","correct":true},{"label":"c","text":"cornerback","correct":false},{"label":"d","text":"wide receiver","correct":false}]},{"number":6,"prompt":"Which of these pieces of equipment would be most helpful in reducing the incidence of commotio cordis?","type":"single","options":[{"label":"a","text":"external ear protection such as wrestling headgear","correct":false},{"label":"b","text":"a hockey helmet with a throat protector","correct":false},{"label":"c","text":"a chest protector","correct":true},{"label":"d","text":"a well-fitted compression sports bra","correct":false}]},{"number":7,"prompt":"Cotton socks are generally better at wicking moisture away from the foot in order to prevent blisters and athlete’s foot than socks made from synthetic materials.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"What is the term for the inflexible internal support in the rear of a running shoe?","type":"single","options":[{"label":"a","text":"the collar","correct":false},{"label":"b","text":"the last","correct":false},{"label":"c","text":"the heel counter","correct":true},{"label":"d","text":"the upper","correct":false}]},{"number":9,"prompt":"For which of these athletes would throat protection be the most important?","type":"single","options":[{"label":"a","text":"a midfielder in field hockey","correct":false},{"label":"b","text":"goalkeeper in lacrosse","correct":true},{"label":"c","text":"an ice hockey defenseman","correct":false},{"label":"d","text":"a softball first baseman","correct":false}]},{"number":10,"prompt":"What are the advantages and disadvantages of a custom molded mouthguard versus a boil and bite mouthguard?","type":"written","referenceAnswer":"advantages: accurate fit, increased comfort, increased compliance, able to speak better; disadvantages: more expensive, several trips to the dentist may be required"}]},{"number":12,"questions":[{"number":1,"prompt":"Which of these would be best to provide compression and support for a hamstring strain?","type":"single","options":[{"label":"a","text":"nonelastic tape","correct":false},{"label":"b","text":"elastic wrap","correct":true},{"label":"c","text":"kinesiology tape","correct":false},{"label":"d","text":"rigid strapping tape","correct":false}]},{"number":2,"prompt":"The benefits of kinesiology tape for treatment of athletic injuries are well-documented.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":3,"prompt":"Although ankle taping has long been the standard functional treatment for lateral ankle sprains, recent studies have compared tape treatments with semi-rigid braces. Which of these statements best summarizes the research in this area?","type":"single","options":[{"label":"a","text":"Tape presented with fewer complications than bracing due to the variance in braces.","correct":false},{"label":"b","text":"Cost should be taken into consideration when comparing taping to bracing because in the long run, taping is cheaper than bracing.","correct":false},{"label":"c","text":"Because braces, unlike tape, are reusable, their relatively low cost along with higher patient satisfaction may make them a better option for functional treatment of lateral ankle sprains.","correct":true},{"label":"d","text":"Braces presented with more skin irritations in the form of blisters due to ill-fitting sizes.","correct":false}]},{"number":4,"prompt":"Which of these ankle braces might be best used during the acute phase of treatment for an inversion or eversion ankle sprain to provide compression and moderate support?","type":"single","options":[{"label":"a","text":"lace-up brace","correct":false},{"label":"b","text":"semirigid brace","correct":false},{"label":"c","text":"air or gel bladder brace","correct":true},{"label":"d","text":"elastic wrap in a figure-of-eight pattern","correct":false}]},{"number":5,"prompt":"One of your basketball players is complaining of pain on the lateral side of his elbow, especially when he makes a fist. You determine that he has lateral epicondylitis. He does not want to sit out of practice and wonders if there is a brace that you can use for practice. What might be an appropriate brace for this player?","type":"single","options":[{"label":"a","text":"elastic wrap","correct":false},{"label":"b","text":"elbow pad","correct":false},{"label":"c","text":"counterforce strap","correct":true},{"label":"d","text":"hinged elbow brace to control hyperextension","correct":false}]},{"number":6,"prompt":"What is the most appropriate padding to use when you need to mold around a specific body part for protection of a contusion?","type":"single","options":[{"label":"a","text":"open-cell foam","correct":true},{"label":"b","text":"closed-cell foam","correct":false},{"label":"c","text":"felt","correct":false},{"label":"d","text":"gel","correct":false}]},{"number":7,"prompt":"The construction of an acromioclavicular joint pad includes the combination of what materials?","type":"single","options":[{"label":"a","text":"fiberglass casting material, open-cell foam, elastic tape","correct":false},{"label":"b","text":"thermoplastic material, open-cell foam, elastic tape, elastic wrap","correct":true},{"label":"c","text":"open-cell foam, closed-cell foam, elastic tape","correct":false},{"label":"d","text":"thermoplastic material, nonelastic tape, felt","correct":false}]},{"number":8,"prompt":"Which of these is NOT true regarding axillary crutch fitting?","type":"single","options":[{"label":"a","text":"There should be 3-5 in. between the axillary pads and the patient’s axilla.","correct":true},{"label":"b","text":"The crutches should be at a 45° angle to the uninvolved foot.","correct":false},{"label":"c","text":"The angle of elbow flexion should be approximately 20°-30°.","correct":false},{"label":"d","text":"The ideal position for the crutches is 6 in. to the side and 2 in. in front of the feet in the tripod stance.","correct":false}]},{"number":9,"prompt":"When navigating stairs with a cane, which of these statements is correct?","type":"single","options":[{"label":"a","text":"To go upstairs, place the cane in the hand of the injured limb. Step up with the uninvolved leg first, then step up on the injured leg.","correct":false},{"label":"b","text":"To go downstairs, lower the involved limb to the next step, then the cane, and finally the uninvolved limb.","correct":false},{"label":"c","text":"To go upstairs, place the cane in the hand opposite the injured limb. Step up with the uninvolved leg first, then step up on the injured leg.","correct":true},{"label":"d","text":"To go downstairs, lower the cane on the next step first, followed by the uninvolved limb and finally the involved limb.","correct":false}]},{"number":10,"prompt":"What is the proper position for taping an athlete’s Achilles tendon?","type":"single","options":[{"label":"a","text":"Patient is in a sitting position with legs extended and the foot is held in a dorsiflexed position.","correct":false},{"label":"b","text":"Patient is prone with foot in a relaxed position off the edge of the table.","correct":true},{"label":"c","text":"Patient is supine with foot in a relaxed position off the edge of the table.","correct":false},{"label":"d","text":"Patient is in a supine position with the leg extended, and the foot is held in a plantarflexed position.","correct":false}]}]},{"number":13,"questions":[{"number":1,"prompt":"Emergency action plans should be _______________.","type":"single","options":[{"label":"a","text":"standardized within the community","correct":false},{"label":"b","text":"site specific","correct":true},{"label":"c","text":"generic","correct":false},{"label":"d","text":"approved by OSHA","correct":false}]},{"number":2,"prompt":"In which of these situations should the EAP be reviewed with all personnel who are listed as being involved in the EAP?","type":"single","options":[{"label":"a","text":"when the OSHA inspection cycle changes","correct":false},{"label":"b","text":"prior to the CAATE site visit","correct":false},{"label":"c","text":"when the EAP is developed or changed","correct":true},{"label":"d","text":"when an employee’s responsibilities change","correct":false}]},{"number":3,"prompt":"Identify 3 types of emergencies addressed in emergency action plans.","type":"written","referenceAnswer":"trauma emergencies, medical-related emergencies, weather-related emergencies, psychological emergencies, mass casualties"},{"number":4,"prompt":"Which of these represents a team-based approach to emergency care?","type":"single","options":[{"label":"a","text":"The team orthopedist is always the person in charge and will direct the rest of the health care team on appropriate actions.","correct":false},{"label":"b","text":"All members of the sports medicine team should be aware of the expertise and skills of the other team members and responsibilities outlined in the EAP.","correct":true},{"label":"c","text":"The EAP should outline specifically who is allowed to perform skills such as starting an IV or performing a concussion examination because of the unique skills of each profession.","correct":false},{"label":"d","text":"The team physician and athletic trainer will perform all on-field emergency care and then hand off the patient to EMS for transport.","correct":false}]},{"number":5,"prompt":"Why would it be important to include custodial staff or athletics administrative staff in an EAP for a public event at the school’s football stadium?","type":"single","options":[{"label":"a","text":"so they can talk to the parents","correct":false},{"label":"b","text":"so they can perform crowd control","correct":false},{"label":"c","text":"so that someone has keys to gates to allow EMS to access the venue","correct":true},{"label":"d","text":"so that they can clean up the area following the emergency","correct":false}]},{"number":6,"prompt":"What would be the best way for the health care team to communicate during an on-field emergency at a football game with 60,000 people in attendance?","type":"single","options":[{"label":"a","text":"cell phone","correct":false},{"label":"b","text":"landline","correct":false},{"label":"c","text":"two-way radio with ear-pieces","correct":true},{"label":"d","text":"hand signals","correct":false}]},{"number":7,"prompt":"When locating AEDs as part of the EAP, which of these is true?","type":"single","options":[{"label":"a","text":"AEDs are kept in a secure place to prevent tampering.","correct":false},{"label":"b","text":"AEDs are available within 3 minutes of all venues.","correct":true},{"label":"c","text":"AEDs are available within 6 minutes of all venues.","correct":false},{"label":"d","text":"AEDs are available immediately on the sidelines for all athletic practices as mandated by federal law.","correct":false}]},{"number":8,"prompt":"Part of the EAP should be step-by-step instructions for different emergencies. Which of these is NOT a recommendation for these step-by-step instructions?","type":"single","options":[{"label":"a","text":"visiting athletic trainers and coaching staffs bring their own EAP","correct":true},{"label":"b","text":"presented in flow chart or bulleted format","correct":false},{"label":"c","text":"no longer than 1 page in length","correct":false},{"label":"d","text":"written to be applicable to many situations","correct":false}]},{"number":9,"prompt":"In the EAP, which of these people would be most appropriate to be given the responsibility of calling EMS if EMS is NOT on-site?","type":"single","options":[{"label":"a","text":"the athletic trainer","correct":false},{"label":"b","text":"an assistant coach","correct":true},{"label":"c","text":"the team physician","correct":false},{"label":"d","text":"a teammate","correct":false}]},{"number":10,"prompt":"How often should the EAP be practiced?","type":"single","options":[{"label":"a","text":"It is a written document, so practice is not really necessary.","correct":false},{"label":"b","text":"It should be practiced a minimum of once yearly, or at the start of each new season.","correct":true},{"label":"c","text":"It should be practiced every 2 years as mandated by state law.","correct":false},{"label":"d","text":"It should be practiced if a previous emergency situation wasn’t handled appropriately.","correct":false}]}]},{"number":14,"questions":[{"number":1,"prompt":"The scene size-up step in emergency assessment consists of all of these EXCEPT","type":"single","options":[{"label":"a","text":"ensuring your own personal safety and the safety of others","correct":false},{"label":"b","text":"determining the mechanism of injury or nature of the illness","correct":false},{"label":"c","text":"establishing whether the patient has a pulse and is breathing","correct":true},{"label":"d","text":"identifying the number of patients","correct":false}]},{"number":2,"prompt":"What is the purpose of the primary assessment?","type":"written","referenceAnswer":"to identify and treat any life-threatening conditions"},{"number":3,"prompt":"What does the AVPU scale assess?","type":"single","options":[{"label":"a","text":"vital signs","correct":false},{"label":"b","text":"mental status","correct":true},{"label":"c","text":"level of pain","correct":false},{"label":"d","text":"airway status","correct":false}]},{"number":4,"prompt":"You approach an older individual who appears to be in stress. His face is drooping on one side, and his left arm is hanging limp. You ask him if he is okay, and it sounds like he has marbles in his mouth, but he asks you to call his wife. What is your response?","type":"single","options":[{"label":"a","text":"You think he is having a myocardial infarction, so call for someone to get the AED.","correct":false},{"label":"b","text":"He may be having a stroke; call 911 immediately.","correct":true},{"label":"c","text":"He looks like he is in pain, so you go through the PQRST assessment.","correct":false},{"label":"d","text":"You take his pulse and it appears okay, so you have him sit down and rest while you call his wife.","correct":false}]},{"number":5,"prompt":"The acronym DCAP-BTLS may be helpful during your secondary assessment of your patient. What does the memory aid DCAP-BTLS stand for?","type":"written","referenceAnswer":"D = deformities and discoloration\nC = contusions\nA = abrasions\nP = penetrations and punctures\nB = burns\nT = tenderness and temperature\nL = lacerations\nS = swelling and symmetry"},{"number":6,"prompt":"Respirations can be assessed for rate, rhythm, depth, and effort. What are possible medical conditions that cause shallower-than-normal respirations?","type":"single","options":[{"label":"a","text":"someone with a fever, heat illness","correct":false},{"label":"b","text":"someone with asthma, rib injury, brain injury","correct":true},{"label":"c","text":"someone who has been exercising","correct":false},{"label":"d","text":"someone who is in very good physical condition","correct":false}]},{"number":7,"prompt":"For suspected exertional heat stroke and hypothermia, rectal temperature is the clinical gold standard for assessing core temperature, but in a minor, tympanic temperature is used due to the invasive nature of taking a rectal temperature.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"What is the term that describes a patient whose excessive sweating is not due to exercise?","type":"single","options":[{"label":"a","text":"cyanotic","correct":false},{"label":"b","text":"pallor","correct":false},{"label":"c","text":"tachycardic","correct":false},{"label":"d","text":"diaphoretic","correct":true}]},{"number":9,"prompt":"What is the normal range for blood sugar as measured by the blood glucometer?","type":"single","options":[{"label":"a","text":"40-60 mg/dL","correct":false},{"label":"b","text":"60-80 mg/dL","correct":false},{"label":"c","text":"80-100 mg/dL","correct":false},{"label":"d","text":"80-120 mg/dL","correct":true}]},{"number":10,"prompt":"For which of these patients would treatment with epinephrine be appropriate?","type":"single","options":[{"label":"a","text":"the athlete who collapses at practice and now has a thready pulse and shallow breathing","correct":false},{"label":"b","text":"an athlete who was stung by a wasp and now is having difficulty breathing as his throat is swelling shut","correct":true},{"label":"c","text":"an athlete with an open tib-fib fracture who is in extreme pain","correct":false},{"label":"d","text":"a diabetic athlete who is lethargic and starting to lose consciousness","correct":false}]}]},{"number":15,"questions":[{"number":1,"prompt":"The inflammatory process is consistent regardless of the type of soft tissue that is injured.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":2,"prompt":"Treatments during the first 48 hours of an acute injury should focus on ___________.","type":"single","options":[{"label":"a","text":"promoting tissue healing","correct":false},{"label":"b","text":"controlling pain and inflammation","correct":true},{"label":"c","text":"increasing range of motion","correct":false},{"label":"d","text":"slow progression of stretching, strengthening, and proprioception","correct":false}]},{"number":3,"prompt":"Bone growth and remodeling occur in direct response to forces that are placed on the tissue. What is the name of this physiological effect?","type":"single","options":[{"label":"a","text":"stress-response law","correct":false},{"label":"b","text":"bone stress response","correct":false},{"label":"c","text":"Wolff’s law","correct":true},{"label":"d","text":"osteopenia","correct":false}]},{"number":4,"prompt":"What is the name of the area between the epiphysis and the diaphysis of a long bone?","type":"single","options":[{"label":"a","text":"metaphysis","correct":true},{"label":"b","text":"trabecular bone","correct":false},{"label":"c","text":"cortical bone","correct":false},{"label":"d","text":"periosteum","correct":false}]},{"number":5,"prompt":"_____________ are responsible for bone reabsorption association with bone breakdown.","type":"written","referenceAnswer":"Osteoclasts"},{"number":6,"prompt":"Which of these is an example of an apophyseal injury that may occur in an 8to 15-year-old patient?","type":"single","options":[{"label":"a","text":"osteochondrosis","correct":false},{"label":"b","text":"Salter-Harris type IV","correct":false},{"label":"c","text":"periostitis","correct":false},{"label":"d","text":"Sever’s disease","correct":true}]},{"number":7,"prompt":"List three obstructions to bone healing.","type":"written","referenceAnswer":"poor blood supply, poor nutrition, infection, age, malalignment of fracture site"},{"number":8,"prompt":"Which of these are myelinated by Schwann cells to allow for more rapid transmission of impulses?","type":"single","options":[{"label":"a","text":"dendrites","correct":false},{"label":"b","text":"axonal terminals","correct":false},{"label":"c","text":"fascicles","correct":false},{"label":"d","text":"axons","correct":true}]},{"number":9,"prompt":"When nerve conduction is physiologically blocked within the affected axon, no conduction occurs across the injured area, but all connective tissue coverings of the nerve are intact, and conduction proximal to and distal to the injured area is intact. What is this called?","type":"single","options":[{"label":"a","text":"axonotmesis","correct":false},{"label":"b","text":"neurotmesis","correct":false},{"label":"c","text":"neuropraxia","correct":true},{"label":"d","text":"Wallerian degeneration","correct":false}]},{"number":10,"prompt":"Sensory nerves are more resilient and have better recover rates than motor nerves and will regenerate at a rate of approximately 1 mm per day beginning about 4 weeks after injury occurs.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]}]},{"number":16,"questions":[{"number":1,"prompt":"Which of these is NOT part of the history component of assessment?","type":"single","options":[{"label":"a","text":"chief complaint","correct":false},{"label":"b","text":"reflex testing","correct":true},{"label":"c","text":"description of present illness or injury","correct":false},{"label":"d","text":"review of symptoms","correct":false}]},{"number":2,"prompt":"Outcome measures should be based on the clinician’s experience and then shared with the patient as part of the treatment plan.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":3,"prompt":"The patient independently moves the area being evaluated, without assistance from the athletic trainer. What kind of range of motion is this?","type":"single","options":[{"label":"a","text":"passive","correct":false},{"label":"b","text":"active","correct":true},{"label":"c","text":"resisted","correct":false},{"label":"d","text":"active assistive","correct":false}]},{"number":4,"prompt":"Which of these is a good example of a hard joint end feel during range-of-motion testing?","type":"single","options":[{"label":"a","text":"elbow flexion","correct":false},{"label":"b","text":"knee flexion","correct":false},{"label":"c","text":"forearm supination","correct":false},{"label":"d","text":"elbow extension","correct":true}]},{"number":5,"prompt":"Which of these would best describe a muscle-strength grading of poor (2)?","type":"single","options":[{"label":"a","text":"full ROM against gravity, maximal resistance","correct":false},{"label":"b","text":"full ROM against gravity","correct":false},{"label":"c","text":"full ROM against gravity, moderate resistance","correct":false},{"label":"d","text":"full ROM with gravity eliminated","correct":true}]},{"number":6,"prompt":"Which of these measures maximal force of a muscle through a range of motion against a fixed velocity?","type":"single","options":[{"label":"a","text":"isotonic","correct":false},{"label":"b","text":"isometric","correct":false},{"label":"c","text":"isokinetic","correct":true},{"label":"d","text":"concentric","correct":false}]},{"number":7,"prompt":"During ligamentous stress tests, the athletic trainer is assessing the end feel of the joint, attempting to stress the ligament and capsule. If the end feel is described as soft, what is your assessment?","type":"single","options":[{"label":"a","text":"A soft end feel is a normal, non-pathological finding of any joint.","correct":false},{"label":"b","text":"A soft end feel can mean laxity in the ligament, indicative of a sprain.","correct":true},{"label":"c","text":"A soft end feel indicates a complete rupture of the ligament.","correct":false},{"label":"d","text":"A soft end feel can mean there is laxity in the ligament, indicative a partial strain.","correct":false}]},{"number":8,"prompt":"Which of the following involves an area of skin innervated by a spinal nerve root?","type":"single","options":[{"label":"a","text":"dermatomes","correct":true},{"label":"b","text":"myotomes","correct":false},{"label":"c","text":"sclerotomes","correct":false},{"label":"d","text":"reflexes","correct":false}]},{"number":9,"prompt":"The biceps deep tendon reflex tests the integrity of which nerve root(s)?","type":"single","options":[{"label":"a","text":"C1, C2","correct":false},{"label":"b","text":"C7","correct":false},{"label":"c","text":"C5, C6","correct":true},{"label":"d","text":"C4, C5","correct":false}]},{"number":10,"prompt":"How would you test the abducens (cranial nerve VI)?","type":"single","options":[{"label":"a","text":"Use a penlight to elicit pupil reaction.","correct":false},{"label":"b","text":"Have the patient follow your finger from side to side with their eyes.","correct":true},{"label":"c","text":"Use a tongue depressor to elicit the gag reflex.","correct":false},{"label":"d","text":"Have the athlete smell something.","correct":false}]}]},{"number":17,"questions":[{"number":1,"prompt":"Which of the following correctly identifies the five primary areas in the continuum of care for patients that medical imaging serves?","type":"single","options":[{"label":"a","text":"diagnosis; preparticipation screening, when indicated; informing a treatment or rehabilitation plan; diagnostic procedures; and return to participation or activities of daily living","correct":true},{"label":"b","text":"diagnosis; emergency treatment; surgical planning; insurance authorization; and return to work","correct":false},{"label":"c","text":"injury prevention; preparticipation screening; prescribing rehabilitation; interpreting imaging reports; and return to sport","correct":false},{"label":"d","text":"diagnostic procedures; patient transportation; image archiving; medication management; and discharge planning","correct":false}]},{"number":2,"prompt":"A radiograph without a contrast agent can distinguish all of the following EXCEPT?","type":"single","options":[{"label":"a","text":"air","correct":false},{"label":"b","text":"bone","correct":false},{"label":"c","text":"ligaments","correct":true},{"label":"d","text":"fat","correct":false}]},{"number":3,"prompt":"Which of these diagnostic imaging techniques does NOT use radiation?","type":"single","options":[{"label":"a","text":"X-rays","correct":false},{"label":"b","text":"radiographs","correct":false},{"label":"c","text":"CT scan","correct":false},{"label":"d","text":"fMRI","correct":true}]},{"number":4,"prompt":"Which of these statements is TRUE regarding diagnostic medical sonography (DMS)?","type":"single","options":[{"label":"a","text":"It cannot provide real-time visualization of underlying tissue.","correct":false},{"label":"b","text":"It can be used to help guide invasive procedures.","correct":true},{"label":"c","text":"The transducer must continually be moved because of the heating effect on the underlying tissue.","correct":false},{"label":"d","text":"It is invasive.","correct":false}]},{"number":5,"prompt":"Which of these uses small amounts of radioactive materials (tracers) injected, swallowed, or inhaled to identify diseases and conditions in the body?","type":"single","options":[{"label":"a","text":"magnetic resonance imaging with contrast","correct":false},{"label":"b","text":"PET scan","correct":true},{"label":"c","text":"radiographs with barium","correct":false},{"label":"d","text":"CT with barium","correct":false}]},{"number":6,"prompt":"Who is the person most often responsible for reading the image taken of the patient?","type":"single","options":[{"label":"a","text":"radiologist","correct":true},{"label":"b","text":"primary care physician","correct":false},{"label":"c","text":"radiology technologist","correct":false},{"label":"d","text":"nurse practitioner","correct":false}]},{"number":7,"prompt":"Which of these is used to view not only the anatomical structures but also the physiological function of organs and tissues?","type":"single","options":[{"label":"a","text":"X-rays","correct":false},{"label":"b","text":"MRI","correct":false},{"label":"c","text":"SPECT","correct":true},{"label":"d","text":"Diagnostic ultrasound","correct":false}]},{"number":8,"prompt":"PACS are used in nearly all facilities that have imaging capabilities. What are PACS designed to do?","type":"single","options":[{"label":"a","text":"Act as an electronic health care record at that facility.","correct":false},{"label":"b","text":"Provide health care providers with remote retrieval and access to patient images.","correct":true},{"label":"c","text":"Provide patients with access to their medical records.","correct":false},{"label":"d","text":"Assist referring physicians and other providers in making the most appropriate imaging for a specific clinical condition.","correct":false}]},{"number":9,"prompt":"Which of these would be most effective in determining a stress fracture of the fibula?","type":"single","options":[{"label":"a","text":"DMS","correct":false},{"label":"b","text":"X-ray","correct":false},{"label":"c","text":"bone-scan","correct":true},{"label":"d","text":"MRI","correct":false}]},{"number":10,"prompt":"Which of these imaging techniques is used to assess cerebral blood flow and neural activity?","type":"single","options":[{"label":"a","text":"PET scan","correct":false},{"label":"b","text":"fMRI","correct":true},{"label":"c","text":"DMS","correct":false},{"label":"d","text":"Doppler ultrasound","correct":false}]}]},{"number":18,"questions":[{"number":1,"prompt":"Which of these breath sounds resembles a snoring sound and may be an indication of pneumonia or chronic bronchitis?","type":"single","options":[{"label":"a","text":"vesicular","correct":false},{"label":"b","text":"rhonchi","correct":true},{"label":"c","text":"crackles","correct":false},{"label":"d","text":"wheeze","correct":false}]},{"number":2,"prompt":"When auscultating the heart with your stethoscope, the normal sounds that you hear sound like “lub” and “dub” and are caused by the closing of the heart valves. The “dub” (or 2nd heart sound) is caused by the closing of which valves?","type":"single","options":[{"label":"a","text":"pulmonary and tricuspid","correct":false},{"label":"b","text":"aortic and tricuspid","correct":false},{"label":"c","text":"aortic and pulmonary","correct":true},{"label":"d","text":"tricuspid and mitral","correct":false}]},{"number":3,"prompt":"Measles, mumps, and rubella had almost been eradicated in the United States but have seen a recent resurgence. Why has there been an increase in cases of these preventable diseases?","type":"single","options":[{"label":"a","text":"children not being vaccinated","correct":true},{"label":"b","text":"children being vaccinated","correct":false}]},{"number":4,"prompt":"One of your patients presents with fever, lymphadenopathy, pharyngitis, splenomegaly, and myalgia. What is your most likely clinical diagnosis?","type":"single","options":[{"label":"a","text":"chickenpox","correct":false},{"label":"b","text":"measles","correct":false},{"label":"c","text":"rubella","correct":false},{"label":"d","text":"mononucleosis","correct":true}]},{"number":5,"prompt":"Which hepatitis is NOT transmitted through blood or parenteral contact with body fluids?","type":"single","options":[{"label":"a","text":"hepatitis A","correct":true},{"label":"b","text":"hepatitis B","correct":false},{"label":"c","text":"hepatitis C","correct":false},{"label":"d","text":"hepatitis D","correct":false}]},{"number":6,"prompt":"Acute onset nausea, vomiting, and diarrhea with diffuse abdominal tenderness are most indicative of which gastrointestinal condition?","type":"single","options":[{"label":"a","text":"GERD","correct":false},{"label":"b","text":"dyspepsia","correct":false},{"label":"c","text":"influenza","correct":false},{"label":"d","text":"gastroenteritis","correct":true}]},{"number":7,"prompt":"Exercise-induced bronchospasm (EIB) is a type of asthma brought on by exercise, and persons with EIB must have asthma too to fit the criteria for EIB diagnosis.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":8,"prompt":"Which genetic disorder is characterized by left ventricular hypertrophy and a nondilated left ventricle with preserved or increased ejection fraction?","type":"single","options":[{"label":"a","text":"hypertension","correct":false},{"label":"b","text":"hypertrophic cardiomyopathy","correct":true},{"label":"c","text":"myocardial hypertrophy (athletic heart)","correct":false},{"label":"d","text":"iron-deficiency anemia","correct":false}]},{"number":9,"prompt":"Which of the following best describes the differences between irritable bowel syndrome (IBS) and inflammatory bowel disease (Crohn’s disease)?","type":"single","options":[{"label":"a","text":"IBS is a diarrheal disease of rapid onset caused by a virus such as rotavirus or a bacterium such as E. coli.","correct":false},{"label":"b","text":"Crohn’s disease is an autoimmune response resulting in chronic inflammation of the bowel.","correct":true},{"label":"c","text":"IBS presents with fever and myalgias, while Crohn’s disease doesn’t.","correct":false},{"label":"d","text":"Crohn’s disease is multifactorial, but treatment often focuses on decreasing stress.","correct":false}]},{"number":10,"prompt":"What is the term for the severe or frequent menstrual cramps and pelvic pain associated with menstruation?","type":"single","options":[{"label":"a","text":"oligomenorrhea","correct":false},{"label":"b","text":"primary amenorrhea","correct":false},{"label":"c","text":"secondary amenorrhea","correct":false},{"label":"d","text":"dysmenorrhea","correct":true}]}]},{"number":19,"questions":[{"number":1,"prompt":"Which of the following lists three barriers to seeking mental health services?","type":"single","options":[{"label":"a","text":"cultural stigma or societal perceptions about seeking treatment, socioeconomic barriers, and lack of providers in the client’s geographic area","correct":true},{"label":"b","text":"accurate understanding of mental illness, strong self-awareness, and access to local providers","correct":false},{"label":"c","text":"high perceived need for treatment, willingness to take medication, and a desire for professional assistance","correct":false},{"label":"d","text":"adequate financial resources, confidence in treatment, and support from family members","correct":false}]},{"number":2,"prompt":"Which of the following is considered a mood or affective disorder?","type":"single","options":[{"label":"a","text":"social anxiety disorder","correct":false},{"label":"b","text":"obsessive-compulsive disorder","correct":false},{"label":"c","text":"panic disorder","correct":false},{"label":"d","text":"bipolar disorder","correct":true}]},{"number":3,"prompt":"State anxiety is a transient characteristic level of unpleasant emotional or physical arousal in the current moment.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":4,"prompt":"Which of the following is characterized by excessive worry on more days than not for at least 6 months, difficulty controlling the worry, and is associated with restlessness, difficulty concentrating, irritability, and sleep disturbance?","type":"single","options":[{"label":"a","text":"seasonal affective disorder","correct":false},{"label":"b","text":"post-traumatic stress disorder","correct":false},{"label":"c","text":"panic disorder","correct":false},{"label":"d","text":"general anxiety disorder","correct":true}]},{"number":5,"prompt":"Which of these is true about student athletes and substance use?","type":"single","options":[{"label":"a","text":"Females are more likely to use substances than males.","correct":false},{"label":"b","text":"Alcohol and drug use can commonly co-occur with other mental health disorders.","correct":true},{"label":"c","text":"Student–athletes are more likely to use substances during the season to improve performance than during the off-season.","correct":false},{"label":"d","text":"Student–athletes don’t typically use or abuse substances because of the potential of being caught on a drug test.","correct":false}]},{"number":6,"prompt":"Which of the following is recurrent episodes of binge eating, followed by intense feelings of guilt and shame that lead to self-induced vomiting or use of laxatives and diuretics?","type":"single","options":[{"label":"a","text":"anorexia nervosa","correct":false},{"label":"b","text":"bulimia nervosa","correct":true},{"label":"c","text":"binge-eating disorder","correct":false},{"label":"d","text":"body dysmorphic disorder","correct":false}]},{"number":7,"prompt":"According to the integrated model of psychological response to sport injury and the rehabilitation process, which three interrelated aspects make up the patient’s psychosocial response?","type":"single","options":[{"label":"a","text":"cognition, affect, and behavior","correct":true},{"label":"b","text":"gender, age, and injury history","correct":false},{"label":"c","text":"depression, anxiety, and fatigue","correct":false},{"label":"d","text":"rehabilitation attendance, exercise adherence, and substance misuse","correct":false}]},{"number":8,"prompt":"Which of the following lists three relaxation techniques that may help reduce a patient’s distress and excess tension during rehabilitation or return to sport?","type":"single","options":[{"label":"a","text":"diaphragmatic breathing, progressive muscle relaxation, and meditation","correct":true},{"label":"b","text":"goal setting, self-talk, and mental imagery","correct":false},{"label":"c","text":"cognitive appraisal, behavioral coping, and social support","correct":false},{"label":"d","text":"motivation, rehabilitation adherence, and injury-history assessment","correct":false}]},{"number":9,"prompt":"What is the term for the ability to identify, understand, and manage emotions in order to manage stress, communicate effectively, empathize with others, overcome challenges, and resolve conflict?","type":"single","options":[{"label":"a","text":"relaxation techniques","correct":false},{"label":"b","text":"goal setting","correct":false},{"label":"c","text":"mental imagery","correct":false},{"label":"d","text":"emotional intelligence","correct":true}]},{"number":10,"prompt":"When a PGA professional visualizes the 20-foot putt rolling down the hill, breaking left slightly and going into the hole, they are using which technique?","type":"single","options":[{"label":"a","text":"positive self-talk","correct":false},{"label":"b","text":"mental imagery","correct":true},{"label":"c","text":"instructional self-talk","correct":false},{"label":"d","text":"focus","correct":false}]}]},{"number":20,"questions":[{"number":1,"prompt":"Communication skills are essential when working with any patient population, especially when communicating with athletes who have special needs. Which of these strategies would be useful when providing care for a patient who is blind?","type":"single","options":[{"label":"a","text":"Explain things more loudly and slowly to the patient.","correct":false},{"label":"b","text":"Speak to the person who escorted the athlete into the clinic.","correct":false},{"label":"c","text":"Be sure to sit down to speak at eye level with the patient.","correct":false},{"label":"d","text":"Explain what you are going to do and allow the athlete to feel the equipment if she is unfamiliar with it.","correct":true}]},{"number":2,"prompt":"Which of the following identifies three special considerations that athletic trainers should recognize when working with tactical athletes?","type":"single","options":[{"label":"a","text":"psychological components of performing duties and returning to duty; use of a self-contained breathing apparatus; and gear or clothing that may restrict movement and alter mechanics","correct":true},{"label":"b","text":"stair climbing; dragging and carrying people or equipment; and battling wilderness fires","correct":false},{"label":"c","text":"lower extremity injuries; lower back injuries; and strains, sprains, and fractures","correct":false},{"label":"d","text":"carrying heavy loads; moving in and out of vehicles; and navigating obstacles","correct":false}]},{"number":3,"prompt":"Which of these is considered a common cause of injury in the pediatric athlete?","type":"single","options":[{"label":"a","text":"multi-sport participation","correct":false},{"label":"b","text":"adequate rest","correct":false},{"label":"c","text":"decreased joint mobility","correct":false},{"label":"d","text":"improper technique","correct":true}]},{"number":4,"prompt":"Which of the following lists three warning signs indicating that an athlete who is pregnant should terminate exercise?","type":"single","options":[{"label":"a","text":"abdominal pain, cramps, or contractions before the due date; calf pain or swelling; and vaginal bleeding","correct":true},{"label":"b","text":"increased caloric intake, increased cardiac output, and weight gain","correct":false},{"label":"c","text":"training in a supine position, performing the Valsalva maneuver, and participating in activities with a high risk of falling","correct":false},{"label":"d","text":"balance difficulties, joint hypermobility, and breathing constraints caused by the growing uterus","correct":false}]},{"number":5,"prompt":"According to the U.S. Association of Blind Athletes (USABA), what is the classification of an athlete who is able to recognize the shape of hand to visual acuity of 20/600?","type":"single","options":[{"label":"a","text":"B1","correct":false},{"label":"b","text":"B2","correct":true},{"label":"c","text":"B3","correct":false},{"label":"d","text":"B4","correct":false}]},{"number":6,"prompt":"_____________ is the preferred term for people who share the same social structures, cultural views, and history and use American Sign Language as their primary mode of communication and ____ is the term for individuals with some hearing loss.","type":"written","referenceAnswer":"Deaf, Hard of Hearing"},{"number":7,"prompt":"What type of hearing loss is due to problems in the ear canal, eardrum, or middle ear?","type":"single","options":[{"label":"a","text":"conductive","correct":true},{"label":"b","text":"sensorineural","correct":false},{"label":"c","text":"mixed","correct":false},{"label":"d","text":"obstructive","correct":false}]},{"number":8,"prompt":"Which of these is NOT considered a common medical condition for athletes with amputations?","type":"single","options":[{"label":"a","text":"skin breakdown","correct":false},{"label":"b","text":"choke syndrome","correct":false},{"label":"c","text":"autonomic dysreflexia","correct":true},{"label":"d","text":"contractures","correct":false}]},{"number":9,"prompt":"Athletes with spinal cord injury have the same resting heart rates and lower blood pressures as able-bodied athletes.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":10,"prompt":"Which two medical concerns should be addressed during the preparticipation physical examination of an athlete with Down syndrome?","type":"single","options":[{"label":"a","text":"cardiac issues and atlantoaxial instability","correct":true},{"label":"b","text":"low back pain and knee osteoarthritis","correct":false},{"label":"c","text":"preterm labor and placental injury","correct":false},{"label":"d","text":"deafness and seizure medication effects","correct":false}]}]},{"number":21,"questions":[{"number":1,"prompt":"Which of the following correctly lists the five categories of therapeutic modalities?","type":"single","options":[{"label":"a","text":"thermal, electrical, electromagnetic, sound, and mechanical","correct":true},{"label":"b","text":"thermal, chemical, electromagnetic, sound, and mechanical","correct":false},{"label":"c","text":"thermal, electrical, electromagnetic, pharmacological, and mechanical","correct":false},{"label":"d","text":"thermal, electrical, electromagnetic, sound, and surgical","correct":false}]},{"number":2,"prompt":"What is the term for the transfer of heat from a warmer object to a cooler object?","type":"single","options":[{"label":"a","text":"conduction","correct":true},{"label":"b","text":"convection","correct":false},{"label":"c","text":"radiation","correct":false},{"label":"d","text":"conversion","correct":false}]},{"number":3,"prompt":"What is the term for the combination of exercise with cold application?","type":"single","options":[{"label":"a","text":"thermogenics","correct":false},{"label":"b","text":"cryotherapy","correct":false},{"label":"c","text":"cryokinetics","correct":true},{"label":"d","text":"fluidotherapy","correct":false}]},{"number":4,"prompt":"Which of these would be a contraindication for transcutaneous electrical neuromuscular stimulation (TENS)?","type":"single","options":[{"label":"a","text":"back spasms","correct":false},{"label":"b","text":"thrombosis","correct":true},{"label":"c","text":"acute pain","correct":false},{"label":"d","text":"depression","correct":false}]},{"number":5,"prompt":"What is the term for measuring muscular contractions through visual or auditory signals to assist patients in strengthening and muscular and postural control?","type":"single","options":[{"label":"a","text":"high voltage galvanic stimulation (HVGC)","correct":false},{"label":"b","text":"interferential current","correct":false},{"label":"c","text":"biofeedback","correct":true},{"label":"d","text":"Russian stimulation","correct":false}]},{"number":6,"prompt":"Diathermy therapies are used particularly when no motor or sensory stimulation is desired, but a heating effect in the tissues in warranted.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":7,"prompt":"Which of these is NOT an indication for low-level LASER therapy?","type":"single","options":[{"label":"a","text":"wound healing","correct":false},{"label":"b","text":"reducing inflammation","correct":false},{"label":"c","text":"analgesia","correct":false},{"label":"d","text":"muscle atrophy","correct":true}]},{"number":8,"prompt":"Marissa wants to use a therapeutic modality to provide heat to a tennis player’s forearm extensor muscles. Which ultrasound setting would be the most effective in increasing the tissue temperature of the muscle?","type":"single","options":[{"label":"a","text":"1 MHZ continuous ultrasound for 7 minutes","correct":false},{"label":"b","text":"3 MHZ continuous ultrasound for 5 minutes","correct":true},{"label":"c","text":"1 MHZ pulsed ultrasound for 7 minutes","correct":false},{"label":"d","text":"1 MHZ continuous ultrasound for 10 minutes using the water technique","correct":false}]},{"number":9,"prompt":"What is the term for delivering a medication into the tissues using electrical polarity?","type":"single","options":[{"label":"a","text":"iontophoresis","correct":true},{"label":"b","text":"vapocoolant","correct":false},{"label":"c","text":"cupping","correct":false},{"label":"d","text":"phonophoresis","correct":false}]},{"number":10,"prompt":"Which of these massage techniques would be the most appropriate treatment pre-activity?","type":"single","options":[{"label":"a","text":"tapotement","correct":false},{"label":"b","text":"petrissage","correct":true},{"label":"c","text":"effleurage","correct":false},{"label":"d","text":"friction","correct":false}]}]},{"number":22,"questions":[{"number":1,"prompt":"Muscle atrophy occurs only after 2 weeks of immobilization or disuse.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":2,"prompt":"Which of these rehabilitation components would be performed last?","type":"single","options":[{"label":"a","text":"control and minimize inflammation","correct":false},{"label":"b","text":"increase range of motion","correct":false},{"label":"c","text":"increase muscular endurance","correct":true},{"label":"d","text":"increase neuromuscular control","correct":false}]},{"number":3,"prompt":"What is the term for the use of appropriate strengthening concepts across the phases of rehabilitation based on tissue healing, patient feedback, and safety?","type":"single","options":[{"label":"a","text":"muscular strengthening","correct":false},{"label":"b","text":"progressive resistance exercises","correct":true},{"label":"c","text":"gradual onset strengthening","correct":false},{"label":"d","text":"neuromuscular gradation","correct":false}]},{"number":4,"prompt":"Which of these strengthening techniques would typically be used first?","type":"single","options":[{"label":"a","text":"isometric","correct":true},{"label":"b","text":"isotonic","correct":false},{"label":"c","text":"isokinetic","correct":false},{"label":"d","text":"progressive resistance exercises","correct":false}]},{"number":5,"prompt":"Isokinetic exercises, unlike isotonic exercises, can only be performed concentrically.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":6,"prompt":"What is the term for the body’s ability to sense position in space through and during movement?","type":"single","options":[{"label":"a","text":"agility","correct":false},{"label":"b","text":"dynamic stability","correct":false},{"label":"c","text":"proprioception","correct":false},{"label":"d","text":"kinesthetic awareness","correct":true}]},{"number":7,"prompt":"Which of these statements about neuromuscular training is true?","type":"single","options":[{"label":"a","text":"There is minimal evidence supporting the benefits of neuromuscular training to enhance performance in agility, jumping. and balance training.","correct":false},{"label":"b","text":"Evidence supports that neuromuscular training after injury may prevent recurrent ankle and knee injuries.","correct":true},{"label":"c","text":"Evidence supports the benefits of neuromuscular control training on the effects of strength and power compared to plyometric or strength training.","correct":false},{"label":"d","text":"Kinesthetic awareness and dynamic stability are developed through static proprioceptive exercises.","correct":false}]},{"number":8,"prompt":"What is the term for an exercise that is performed when an extremity is not fixed to an object like the floor or wall, or aided by another person?","type":"single","options":[{"label":"a","text":"open kinetic chain exercise","correct":true},{"label":"b","text":"proprioceptive neuromuscular facilitation exercise","correct":false},{"label":"c","text":"practitioner-assisted therapeutic exercise","correct":false},{"label":"d","text":"closed kinetic chain exercise","correct":false}]},{"number":9,"prompt":"Joint mobilization is a passive technique intended to increase range of motion and enhance function. Which of these techniques uses oscillations during joint mobilizations?","type":"single","options":[{"label":"a","text":"Maitland","correct":true},{"label":"b","text":"McKenzie","correct":false},{"label":"c","text":"Mulligan","correct":false},{"label":"d","text":"Katlenborn","correct":false}]},{"number":10,"prompt":"Which of the following techniques uses a position of patient comfort to target the somatic dysfunction that may be the source of myofascial pain?","type":"single","options":[{"label":"a","text":"strain/counterstrain","correct":false},{"label":"b","text":"positional release","correct":true},{"label":"c","text":"soft-tissue mobilization","correct":false},{"label":"d","text":"IASTM","correct":false}]}]},{"number":23,"questions":[{"number":1,"prompt":"What is the term for the study of how the body processes a drug including administration, distribution, metabolism, and elimination?","type":"single","options":[{"label":"a","text":"pharmacodynamics","correct":false},{"label":"b","text":"pharmacokinetics","correct":true},{"label":"c","text":"phonophoresis","correct":false},{"label":"d","text":"pharmacology","correct":false}]},{"number":2,"prompt":"What is the term for the process by which a drug moves between the blood stream and other tissues in the body?","type":"single","options":[{"label":"a","text":"absorption","correct":false},{"label":"b","text":"elimination","correct":false},{"label":"c","text":"distribution","correct":true},{"label":"d","text":"metabolism","correct":false}]},{"number":3,"prompt":"By law, when traveling with a team, the athletic trainer may be given permission by the team physician to give an athlete one dose of a prescribed medication.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":4,"prompt":"Describe the difference between a formulary and a pharmacy.","type":"written","referenceAnswer":"A formulary is an entity that maintains a list of drugs that are available. A pharmacy sells, dispenses, and can prepare medications (compounding)."},{"number":5,"prompt":"Patient records for administration and dispensation of drugs must include information on both a log sheet for drugs and in the patient’s file and should include all of these EXCEPT","type":"single","options":[{"label":"a","text":"drug administered","correct":false},{"label":"b","text":"dose","correct":false},{"label":"c","text":"quantity","correct":false},{"label":"d","text":"expiration date of medication","correct":true}]},{"number":6,"prompt":"Schedule III drugs have a low-to-moderate potential for abuse or dependency. Which of these is considered a Schedule III drug?","type":"single","options":[{"label":"a","text":"Robitussin AC","correct":false},{"label":"b","text":"LSD","correct":false},{"label":"c","text":"OxyContin","correct":false},{"label":"d","text":"Tylenol with codeine","correct":true}]},{"number":7,"prompt":"Which of the following best describes Flexeril?","type":"single","options":[{"label":"a","text":"an antipyretic","correct":false},{"label":"b","text":"an anti-inflammatory","correct":false},{"label":"c","text":"an analgesic","correct":false},{"label":"d","text":"a muscle relaxer","correct":true}]},{"number":8,"prompt":"Which of the following is best used as a rescue inhaler medication to provide immediate relief from asthma?","type":"single","options":[{"label":"a","text":"a short-acting beta agonist such as Albuterol","correct":true},{"label":"b","text":"a long-acting beta agonist such as Serevent","correct":false},{"label":"c","text":"a short-acting corticosteroid such as Pulmicort","correct":false},{"label":"d","text":"a short-acting antihistamine such as Flonase","correct":false}]},{"number":9,"prompt":"The first line of medications used to treat gastrointestinal upset is generally proton pump inhibitors like Prilosec.","type":"single","options":[{"label":"a","text":"true","correct":false},{"label":"b","text":"false","correct":true}]},{"number":10,"prompt":"One of your patients was prescribed a 10-day course of antibiotics for strep throat. After 4 days of taking his medication, he is having GI distress and has decided to discontinue taking his antibiotics. What advice would you give your patient?","type":"written","referenceAnswer":"Continue to take the antibiotic and refer back to the prescribing physician because not completely eliminating the bacteria may make it stronger and resistant to future antibiotic treatment."}]},{"number":24,"questions":[{"number":1,"prompt":"Which of these would be most appropriate to use just until the swelling decreases for an acute ulna fracture with considerable swelling, given that the patient will have surgery once the swelling decreases.","type":"single","options":[{"label":"a","text":"a short-arm fiberglass cast","correct":false},{"label":"b","text":"a short-arm plaster cast with thumb spica","correct":false},{"label":"c","text":"an Ortho-Glass splint or bi-valved cast secured with elastic wrap","correct":true},{"label":"d","text":"an over-the-elbow fiberglass cast","correct":false}]},{"number":2,"prompt":"What are pros and cons of fiberglass casting material?","type":"written","referenceAnswer":"pros: more breathable, water resistant, less messy, easily transportable\ncons: not as forgiving to substantial angles, expires more quickly, expensive"},{"number":3,"prompt":"Which of the following best describes the fibroblastic repair phase?","type":"single","options":[{"label":"a","text":"callus continues to condition and harden via osteoclastic destruction of necrotic tissue","correct":false},{"label":"b","text":"increased cell proliferation, capillary budding, and revascularization","correct":true},{"label":"c","text":"platelets activate outside of the blood vessel by binding to exposed collagen fibers","correct":false},{"label":"d","text":"chemoattractants are released, recruiting platelets, erythrocytes, and fibrin to form a clot","correct":false}]},{"number":4,"prompt":"Full remodeling can take 6 months to more than 2 years depending on the age, health, and activity level of the individual.","type":"single","options":[{"label":"a","text":"true","correct":true},{"label":"b","text":"false","correct":false}]},{"number":5,"prompt":"Which of the following lists three common contraindications to casting?","type":"single","options":[{"label":"a","text":"allergic reactions, distal neuropathy, and open sores or wounds","correct":true},{"label":"b","text":"a nondisplaced fracture, controlled swelling, and access to follow-up care","correct":false},{"label":"c","text":"a reduced fracture, a need for immobilization, and healthy, intact skin","correct":false},{"label":"d","text":"injury stabilization, protection from additional stress, and sustained stretching","correct":false}]},{"number":6,"prompt":"Which of these would be the most appropriate size of stockinette to use for a 12-year-old gymnast needing a short-leg cast?","type":"single","options":[{"label":"a","text":"1 in.","correct":false},{"label":"b","text":"2 in.","correct":true},{"label":"c","text":"3 in.","correct":false},{"label":"d","text":"4 in.","correct":false}]},{"number":7,"prompt":"According to the literature, how many layers of soft roll have been identified as substantial enough to provide adequate padding and skin protection from the saw blade at time of removal, while resulting in the least amount of fitting distortion once settling has occurred?","type":"single","options":[{"label":"a","text":"2","correct":false},{"label":"b","text":"3","correct":false},{"label":"c","text":"4","correct":true},{"label":"d","text":"5","correct":false}]},{"number":8,"prompt":"When removing a cast, it is important to remember that most patients have never had a cast removed. What are the three things you should communicate to your patient?","type":"written","referenceAnswer":"Take the time to explain, in detail, that you are going to remove the cast, how you are going to do it, and what tools you will be using. While the saw is capable of causing friction burns, or even lacerations, if enough pressure is applied, your explanation of how it will feel on the skin, the safety measures built into the tools you are using (such as the blunted points of tape/bandage scissors, or the oscillating motion of the saw blade), and a description of the techniques you will use will help ensure the patient’s safety."},{"number":9,"prompt":"Which of these injuries would NOT be best treated with a short-arm cast?","type":"single","options":[{"label":"a","text":"distal radius and ulnar fracture","correct":false},{"label":"b","text":"radial styloid fracture","correct":false},{"label":"c","text":"carpal fracture","correct":false},{"label":"d","text":"scaphoid fracture","correct":true}]},{"number":10,"prompt":"When applying a long-arm cast for a distal fracture of the forearm, in what position should the forearm be placed during casting to decrease the pull of the pronator forces that act as deforming forces during healing?","type":"single","options":[{"label":"a","text":"slight supination","correct":false},{"label":"b","text":"full supination","correct":false},{"label":"c","text":"neutral","correct":true},{"label":"d","text":"pronation","correct":false}]}]}];
